[272] = {"Испытание Морского Льва", {"Найдите половинку подвески Ловкости водяного облика и половинку подвески Выносливости водяного облика. Поговорите с жителями Лунной поляны, чтобы узнать, где могут находиться эти предметы.","","Сложите из половинок подвеску Морского Льва. Для этого вам надо находиться рядом со святилищем Ремулоса.","","Отнесите собранную подвеску Дендриту Блеску Звезд в деревню Ночная Гавань, что на Лунной поляне."}},
[273] = {"Снабжение экспедиции", {"Поговорите с Хальдаром."}},
[274] = {"Прямая и черная угроза", {"Сообщите главному инженеру Камнехмылу о нейтрализующем коллоиде."}},
[275] = {"Нарывы на теле земли", {"Убейте 12 трясинных ползунов и вернитесь к Ретилю Стражу Природы в Болотину."}},
[276] = {"Вытоптанные луга", {"Убейте 15 гноллов  из стаи Мохошкуров и 10 полукровок  из стаи Мохошкуров. Вернитесь к Ретилю Стражу Природы в Болотину."}},
[277] = {"Запрет на огонь", {"Принесите Ретилю Стражу Природы 9 необработанных кремней."}},
[278] = {"Прямая и черная угроза", {"Принесите паучий яд, мо'грошский кристалл и слезу кроколиска главному инженеру Плотине."}},
[279] = {"Угроза из глубин", {"Убейте 12 мурлоков из племени Синежабрых.","","Прикончите Жруна и принесите его голову Карлу Борану в Гавань Менетилов."}},
[280] = {"Прямая и черная угроза", {"Проплывите по реке к основанию дамбы, отыщите бочку с порохом и влейте в нее нейтрализующую смесь, чтобы предотвратить взрыв."}},
[281] = {"Украденные товары", {"Обыщите сундуки, бочки и ящики в поселениях мурлоков на побережье."}},
[282] = {"Наблюдения Сенира", {"Поговорите с горным пехотинцем Талосом."}},
[283] = {"Прямая и черная угроза", {"Кажется, нейтрализующая смесь сработала. Вернитесь к главному инженеру Плотине – принесите ему добрые вести."}},
[284] = {"Поиски продолжаются", {"Найдите статуэтку Менетила."}},
[285] = {"Поиски в поселениях мурлоков", {"Продолжите поиски статуэтки Менетила в поселении мурлоков."}},
