[289] = {"Проклятая команда", {"Убейте 13 проклятых матросов, 5 проклятых стражей бухты и первого помощника Снеллига. Принесите табакерку Снеллига первому помощнику Фитсиммонсу в Гавань Менетилов."}},
[290] = {"Очищение", {"Возьмите ключ от сейфа на \"Отважном\" у капитана Халиндора.","","Откройте сейф на \"Отважном\"."}},
