[312] = {"Ограбление тайника Тундры Макгранна", {"Добудьте из пещеры Старого Ледоборода вяленое мясо из краденого ларя Тундры Макгранна."}},
[313] = {"Серая берлога", {"Принесите 8 грив вендиго пилоту Камнекожцу."}},
[314] = {"Защита стада", {"Убейте Вагаша и принесите его клык Рудре Янтарлен на Бараний выгон."}},
