[317] = {"Заготовка продовольствия", {"Принесите 4 куска кабанины и 2 толстых медвежьих шкуры пилоту Брюхинсу в Поселок Сталежара."}},
[318] = {"\"Вечное сияние\"", {"Возьмите бочонок \"Вечного сияния\" у Регольда Ячменовара в Поселке Пивоваров."}},
[319] = {"Услуга за \"Вечное сияние\"", {"Убейте 6 медведей-ледолапов, 8 старых скальных вепрей и 8 снежных леопардов. Вернитесь к Регольду Ячменовару в Поселок Пивоваров."}},
