[338] = {"Зеленые холмы Тернистой долины", {"Соберите все недостающие страницы романа \"Зеленые холмы Тернистой долины\". Когда у вас на руках окажутся все четыре главы, верните их Барнилу."}},
[339] = {"Глава I", {"Принесите 1, 4, 6 и 8 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Кубку, чтобы собрать всю первую главу."}},
[340] = {"Глава II", {"Принесите 10, 11, 14 и 16 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Кубку, чтобы собрать всю вторую главу."}},
[341] = {"Глава III", {"Принесите 18, 20, 21 и 24 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю третью главу."}},
[342] = {"Глава IV", {"Принесите 25, 26 и 27 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Кубку, чтобы собрать всю четвертую главу."}},
[343] = {"Кстати, о стойкости духа", {"Отправляйтесь в Королевскую библиотеку Крепости Штормграда и поговорите с Милтоном Снопом. Он даст вам книгу по металлургии, которая интересует брата Кристофа."}},
