[4293] = {"Проба слизи...", {"Возьмите на пробу образцы слизи из Оскверненного леса. Воспользуйтесь тестовым оборудованием химика Барабоса в Катакомбах, чтобы отобрать 5 наиболее чистых образцов и отдайте их ему."}},
[4294] = {"...и образцы слизнюков", {"Возьмите на пробу образцы слизи из кратера Ун'Горо. Воспользуйтесь тестовым оборудованием химика Барабоса в Катакомбах, чтобы отобрать 5 наиболее чистых образцов и отдайте их ему."}},
