[5930] = {"Дух Великого Медведя", {"Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне."}},
[5931] = {"Возвращение в Дарнасс", {"Вернитесь в Дарнасс и поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария."}},
[5932] = {"Возвращение в Громовой Утес", {"Вернитесь в Громовой Утес и поговорите с Тюраком Руническим Тотемом на Вершине Старейшин."}},
[5943] = {"Караван Гизлтона", {"Проводите караван Гизлтона через Поле Маннорок. О награде поговорите со Смидом: его можно найти в Лагере Заржавня."}},
[6001] = {"Тело и дух", {"Посыпьте лунной пылью Кенария камень лунного совуха в Аубердине, чтобы вызвать Лунокогтя. Победите Лунокогтя, чтобы получить силу его тела и духа.","","Затем поговорите с Матренгилом Медвежьей Лапой в Дарнассе."}},
[6002] = {"Тело и дух", {"Посыпьте лунной пылью Кенария Камень Лунного совуха, что между Мулгором и Степями, чтобы вызвать Лунокогтя. Теперь вам надо побороть Лунокогтя, чтобы заслужить его силу духа и тела.","","Когда выполните это, поговорите с Тюраком Руническим Тотемом в Громовом Утесе."}},
[6027] = {"Книга Древних", {"Отыщите Книгу Древних и принесите ее Азору Альдаморту в башню Этель-Ретор."}},
[6029] = {"Донесение из Круговзора", {"Доставьте донесение из Круговзора офицеру Гарушу из ордена Серебряного Рассвета в Бастион в Западных Чумных землях."}},
[6030] = {"Герцог Николас Зверенхофф.", {"Доставьте книгу \"Исследования речи духов\" Герцогу Николасу Зверенхоффу в Часовню Последней Надежды в Восточных Чумных землях."}},
[6061] = {"Приручение зверя", {"Приручите взрослого равнинного долгонога при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта."}},
[6062] = {"Приручение зверя", {"Приручите лютого пятнистого вепря с помощью хлыста приручения. Потренируйтесь, потом верните хлыст приручения Тотару в Колючем Холме."}},
[6063] = {"Приручение зверя", {"С помощью хлыста приручения приручите чащобного тенетника. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар."}},
[6064] = {"Приручение зверя", {"Приручите большого скального вепря с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос."}},
[6065] = {"Путь охотника", {"Поговорите с Йо Колкой Гривой в Деревне Кровавого Копыта."}},
[6069] = {"Путь охотника", {"Поговорите с Тотаром в Колючем Холме."}},
[6071] = {"Путь Охотника", {"Поговорите в Доланааре с Дазаларом."}},
[6074] = {"Путь охотника", {"Поговорите с Грифом Диким Сердцем в Караносе."}},
[6075] = {"Путь охотника", {"Поговорите с Грифом Диким Сердцем в Караносе."}},
[6081] = {"Обучение зверя", {"Поговорите с Ормаком Лютострелом в Оргриммаре."}},
[6082] = {"Приручение зверя", {"Приручите бронескорпа с помощью хлыста приручения. Потренируйтесь, потом вернитесь к Тотару в Колючем Холме."}},
[6083] = {"Приручение зверя", {"Приручите приливного краба с помощью хлыста приручения. Потренируйтесь, потом верните хлыст приручения Тотару в Колючем Холме."}},
[6084] = {"Приручение зверя", {"Приручите снежного леопарда с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос."}},
[6085] = {"Приручение зверя", {"Приручите медведя-ледолапа с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос."}},
[6086] = {"Обучение зверя", {"Поговорите в с Белией Громовым Гранитом в Стальгорне."}},
[6087] = {"Приручение зверя", {"Приручите охотника прерий при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта."}},
[6088] = {"Приручение зверя", {"Приручите перепелятника при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта."}},
[6089] = {"Обучение зверя", {"Поговорите с Хольтом Громовым Рогом в Громовом Утесе."}},
[6101] = {"Приручение зверя", {"С помощью хлыста приручения приручите ночного саблезуба-охотника. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар."}},
[6102] = {"Приручение зверя", {"С помощью хлыста приручите совиного крикуна. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар."}},
[6103] = {"Обучение зверя", {"Поговорите с Иокастой в анклаве Кенария в Дарнассе."}},
[6121] = {"Новый урок", {"Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань."}},
[6122] = {"Основной источник", {"Используйте пустую колбу для взятия пробы воды из устья пещеры у водопада Скалистый.","","Доставьте наполненную колбу Аландариан Песне Ночи в Аубердин, на Темный Берег."}},
[6123] = {"Сбор лекарственных ингредиентов", {"Принесите 5 корешков землекорня и 12 лунных грибов Аландариан Песне Ночи в Аубердине, чтобы она могла сделать целительную мазь."}},
[6124] = {"Исцеление больных", {"Нанесите мазь исцеления животных на 10 больных оленей, обитающих на Темном Берегу, – это должно их исцелить. По слухам, ареал обитания больных оленей – южнее реки Скалистой и севернее Аубердина, а далее – по всей области, вплоть до южных границ Темного Берега, где начинается Ясеневый лес."}},
[6125] = {"Власть над ядом", {"Вернитесь к Матренгилу Медвежьей Лапе в анклав Кенария в Дарнассе."}},
[6126] = {"Новый урок", {"Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань."}},
[6127] = {"Основной источник", {"Используйте пустой пробоотборник Вершины Багрового Тумана для отбора воды из озера на вершине.","","Доставьте наполненный пробоотборник Вершины Багрового Тумана Тонге Руническому Тотему в Перекресток, что в Степях."}},
[6128] = {"Создание лекарства", {"Принесите 5 корешков землекорня и 5 рогов кодо Тонге Руническому Тотему в Перекресток, и он сделает целебную мазь."}},
[6129] = {"Исцеление больных", {"Нанесите мазь исцеления животных на 10 больных газелей, обитающих в северной части Степей, – это должно их вылечить. По слухам, больные газели живут севернее дороги, проходящей через Перекресток с востока на запад."}},
[6130] = {"Власть над ядом", {"Вернитесь к Тюраку Руническому Тотему на Вершину Старейшин в Громовой Утес."}},
[6132] = {"Вытащи меня отсюда!", {"Проводите Мелиццу Жужжалит в лагерь у Кладбища кодо в Пустошах. Поговорите с Хормицем Жужжалитом."}},
[6134] = {"Сбор эктоплазмы", {"Принесите 8 единиц эктоплазмы и ящик призрачных магнитов Хормицу Жужжалиту в Пустоши."}},
[6141] = {"Брат Антон", {"Найдите в Пустошах брата Антона и поговорите с ним."}},
[6142] = {"Наживка из моллюска", {"Найдите 10 кусочков мяса мягкокожего моллюска и принесите Май'Лахии в Деревню Ночных Охотников."}},
[6143] = {"Смерть земноводным!", {"Убейте 7 мирмидонов, 7 наг и 5 колдуний из клана Скользящего Плавника, а затем вернитесь в деревню Сумеречной Охоты и поговорите с Друлзегаром."}},
[6161] = {"Сокровища Ракмора", {"Найдите серебряный и золотой ключи Ракмора, а затем разыщите и отоприте сундук Ракмора."}},
[6162] = {"Последняя битва супруга", {"Убейте властителя Рора и принесите его коготь Дрейка'Сур на заставу Отравленной Крови в Оскверненном лесу."}},
[6181] = {"Срочное сообщение", {"Отнесите записку Льюиса укротителю грифонов Тору."}},
[6261] = {"Дунгар Долгопив", {"Отнесите ящик Озрика к укротителю грифонов Дунгару Долгопиву."}},
[6281] = {"Продолжение пути в Штормград", {"Оплатите укротителю грифонов Тору полет до Штормграда и принесите записку Льюиса Озрику Штрангу в магазинчик \"Ограниченная неуязвимость\", расположенный в районе Старого города."}},
[6282] = {"Угроза со стороны гарпий", {"Землепряд Маггран из Приюта у Солнечного Камня просит вас убить 7 гарпий, 7 душительниц, 7 душегубок и 7 бродяжниц из стаи Кровавой Ярости."}},
[6283] = {"Предводительница клана Кровавой Ярости", {"Маггран из Приюта у Солнечного Камня просит убить Потрошительницу из стаи Кровавой Ярости и принести ему ее останки в доказательство того, что она мертва."}},
[6284] = {"Арахнофобия", {"Убейте Бесселет и принесите клык Бесселет Магграну в Приют у Солнечного Камня."}},
[6285] = {"Возвращение к Льюису", {"Оплатите укротителю грифонов Дунгару Долгопиву полет до Сторожевого холма, а затем отнесите ящик Озрика Льюису."}},
[6301] = {"Цикл возрождения", {"Таммра Поле Ветров из Приюта у Солнечного Камня просит вас собрать 10 семян Геи."}},
[6321] = {"Поставка оружия", {"Отнесите заказ Подрига Каросу Раззоку."}},
[6322] = {"Майкл Гарретт", {"Отправляйтесь к Майклу Гарретту с ящиком Гордона."}},
[6323] = {"Полет в Подгород", {"Оплатите у дрессировщика летучих мышей Кароса Раззока полет до Подгорода, а затем отнесите заказ Подрига Гордону Уиндему в Подгороде."}},
[6324] = {"Обратно к Подригу", {"Оплатите у дрессировщика летучих мышей Майкла Гарретта полет до Гробницы, а затем отдайте ящик Гордона стражу смерти Подригу в Гробнице."}},
[6341] = {"Изобилие Тельдрассила", {"Отнесите коллекцию Нессы к Веспристу."}},
[6342] = {"Полет в Аубердин", {"Совершите полет в Аубердин на гиппогрифе укротителя Весприста и отнесите коллекцию Нессы Лайрду."}},
[6343] = {"Возвращение к Нессе", {"Принесите ответ Лайрда Нессе Песне Теней."}},
[6344] = {"Несса Песня Теней", {"Поговорите с Нессой Песня Теней."}},
[6361] = {"Связка шкур", {"Отнесите связку шкур Зарга укротителю ветрокрылов Девраку из Перекрестка."}},
[6362] = {"Дорога до Громового Утеса", {"Оплатите перелет в Громовой Утес укротителю ветрокрылов Девраку и, оказавшись на месте, отнесите связку шкур Ахану."}},
[6363] = {"Укротитель ветрокрылов Тал", {"Отнесите кожаные вещи Ахану Талу из Громового Утеса."}},
[6364] = {"Возвращение к Джахану", {"Оплатите перелет до Перекрестка у укротителя ветрокрылов Тала, а затем отнесите кожаные вещи Ахану Джахану Ястребиному Крылу."}},
[6365] = {"Мясные продукты в Оргриммар", {"Отнесите мясные продукты Зарга Девраку из Перекрестка."}},
[6381] = {"Новая жизнь", {"Посадите 10 семян Геи в земляные курганы Геи, а затем верните оставшиеся зачарованные семена Геи Таммре в Приют у Солнечного Камня."}},
[6382] = {"Большая охота", {"Поговорите с Сенани Громосерд на заставе Расщепленного Древа в Ясеневом лесу."}},
[6383] = {"Большая охота", nil},
[6384] = {"Дорога до Оргриммара", {"Оплатите полет в Оргриммар укротителю ветрокрылов Девраку и, оказавшись в Оргриммаре, отнесите мясные продукты Зарга Гришке."}},
[6385] = {"Укротитель ветрокрылов Дорас", {"Отнесите письмо Гришки Дорасу из Оргриммара."}},
[6386] = {"Возвращение на Перекресток", {"Оплатите перелет в Перекресток укротителю ветрокрылов Доресу и, оказавшись на месте, передайте письмо Гришки Заргху из Перекрестка."}},
[6387] = {"Награды ученикам", {"Отнесите список Брока Торгруму Боррелсону в Телcамаре."}},
[6388] = {"Грит Турден", {"Отнесите почетные кирки Гриту Турдену в Стальгорне."}},
[6391] = {"Полет в Стальгорн", {"Заплатите укротителю грифонов Торгруму Боррелсону, долетите на грифоне до Стальгорна и отдайте список Брока Голниру Твердопалу."}},
[6392] = {"Возвращение к Броку", {"Заплатите укротителю грифонов Гриту Турдену, долетите на грифоне до Телcамара и отдайте почетные кирки Броку Камнекопу."}},
[6393] = {"Война элементалей", {"Принесите 10 Огненных кристаллов Цунаману в приют Солнечного Камня."}},
[6394] = {"Кирка Тазз'рила", {"Принесите штейгеру Тазз'рилу его кирку."}},
[6395] = {"Последнее желание Марлы", {"Отнесите останки Самуэля Фиппса на могилу Марлы, а затем вернитесь к ученице Элрет."}},
[6401] = {"Кайя жива!", {"Передайте хорошие новости Таммре Поле Ветров, живущей в Приюте у Солнечного Камня."}},
[6421] = {"Ущелье Камнепадов", {"Обследуйте глубины пещеры в ущелье Камнепадов и принесите 10 кристаллов резонита для исследования Мор'рогалу в Приют у Солнечного Камня."}},
[6441] = {"Рога сатира", {"Добудьте 16 рогов сатира для Пиксель на заставе Расщепленного Древа."}},
[6442] = {"Наги на Зорамском взморье", {"Принесите 20 голов наг из клана Зловещего Хвоста Марукайе на Зорамское взморье."}},
[6461] = {"Кровопийцы", {"Ксен'Зилла из Малака'джина просит вас убить 10 ползун из густого мха и 7 моховых ядоплюев."}},
[6462] = {"Оберег троллей", {"Принесите 8 оберегов троллей Митсуве в форт Зорам'гар."}},
[6481] = {"Пробуждение земельника", {"Откройте резонитовую емкость при помощи зачарованного кристалла резонита и затем убейте Гоггерока. Вернитесь к Мор'рогалу с новостями и зачарованным кристаллом резонита."}},
[6482] = {"Свободу Руулу!", {"Сопроводите Руула, затем поговорите с Ями Снежное Копыто на заставе Расщепленного Древа."}},
[6503] = {"Вестницы Ясеневого леса", {"Убейте 9 вестниц Ясеневого леса, а затем вернитесь к Курай'бину на заставу Расщепленного Древа."}},
[6504] = {"Утраченные страницы", {"Найдите 12 пропавших страниц руководства по использованию резака и соберите их по порядку глав 1, 2 и 3. Верните страницы Гурде Печати Гнева близ заставы Расщепленного Древа."}},
[6521] = {"Нечестивый союз", {"Принести голову посла Малкина Вариматрасу в Подгород."}},
[6522] = {"Нечестивый союз", {"Отнесите маленький свиток Вариматрасу в Подгород."}},
[6523] = {"Защита Кайи", {"Проводите Кайю Плоское Копыто до Лагеря Апарахе, затем вернитесь к Макабе Плоскому Копыту, находящемуся поблизости от юго-восточного края Каменного Когтя."}},
[6541] = {"Донесение Кадраку", {"Доложитесь Кадраку в сторожевой башне в северных Степях."}},
[6542] = {"Донесение Кадраку", {"Доложитесь Кадраку в сторожевой башне в северных Степях."}},
[6543] = {"Отчет Песни Войны", {"Распакуйте связку донесений. Доставьте отчеты Песни Войны разведчику, гонцу и всаднику клана Песни Войны. Возьмите у них новые донесения для Кадрака и доставьте ему в северную сторожевую башню в Степях."}},
[6544] = {"Налет Торека", {"Сопровождайте Торека при нападении на Аванпост Среброкрылых и в сражении с Дариэлем Лунным Пламенем, затем доложитесь Эртогу Лютоклыку на заставе Расщепленного Древа."}},
[6545] = {"Сведения гонца клана Песни Войны", nil},
[6546] = {"Сведения всадника из клана Песни Войны", nil},
[6547] = {"Сведения разведчика клана Песни Войны", nil},
[6548] = {"Отомсти за мою деревню", {"Убейте 8 бузотеров и 6 наемников из племени Зловещего Тотема, затем вернитесь к Макабе Плоскому Копыту, ожидающему вас на юго-восточной границе Когтистых гор."}},
[6561] = {"Жестокость Черных Глубин", {"Принесите голову Повелителя сумрака Келриса Башане Руническому Тотему в Громовой Утес."}},
[6562] = {"Угроза из Глубин", {"Поговорите с Дже'неу Санкри в Ясеневом лесу."}},
[6563] = {"Сущность Аку'май", {"Принесите 20 сапфиров Аку'май Дже'неу Санкри в Ясеневый лес."}},
[6564] = {"Верность Древним богам", {"Принесите отсыревшую записку Дже'неу Санкри в Ясеневый лес."}},
[6565] = {"Верность Древним богам", {"Убейте Лоргуса Джетта в Непроглядной Пучине и вернитесь к Дже'неу Санкри в Ясеневый лес."}},
[6571] = {"Поставка для Песни Войны", {"Соберите полностью поставку Песни Войны: лезвия для пил, веревку для бревен, масло и партию топоров Песни Войны для Локе Окарра на заставе Расщепленного Древа."}},
[6581] = {"Пилы Песни Войны", nil},
[6607] = {"Экстремальная рыбалка Ната Пэгла", {"Поймайте для Ната Пэгла следующих рыб:","Махи-махи с берега Туманных Тростников на Болоте Печали.","Ударник Сартериса с побережья Сар'Терис из Пустошей.","Фералас-ахи из реки Вердантис из Фераласа.","Синий плавник Гибельного берега из Тернистой долины.","По выполнении вернитесь к Нату Пэглу."}},
[6608] = {"Больше учить нечему", {"Похоже, Лумак хочет сказать, что ему больше нечему вас учить. Возможно, стоит найти его друга Ната Пэгла – человека, который удит рыбу на островах к югу от Терамора. Кажется, Лумак имеет в виду именно это."}},
[6609] = {"С меня больше нечего взять!", {"Отправляйтесь на Калимдор, в приморский город Терамор. Там к югу от города найдите остров. Нат Пэгл уже ждет."}},
[6610] = {"Мидии с сюрпризом", {"Могиль Быстроруб поручил принести ему следующее:","","12 гигантских яиц. Их можно отыскать у рухов Танариса или других крупных птиц.","","10 кусков острого мяса моллюсков. Разумеется, его добывают у моллюсков!","","20 кусков альтеракского сыра. Из сыроварни!","","Собрав все составляющие, возвращайтесь к Диргу."}},
[6611] = {"Ступай в Прибамбасск!", {"Отправляйтесь в Прибамбасск в пустыне Танарис и поговорите с Могилем Быстрорубом."}},
[6612] = {"Я знаю одного парня...", {"Пойдите в Прибамбасск в пустыне Танарис и поговорите с Могилем Быстрорубом насчет продвижения в поварской карьере."}},
[6621] = {"Король Гиблой Чащи", {"Водрузите знамя Каранга на тотемном кургане Гиблой Чащи. Не дайте фурболгам унитожить знамя. Одолейте вождя Мургута и принесите тотем Мургута Карангу Амаккару в Зорам'гар."}},
[6622] = {"Очередь на медобслуживание", {"Окажите помощь пациентам, используя для перевязки их ран очередные перевязочные бинты. Вы должны оказать помощь 15 пациентам прежде, чем 6 из них успеют умереть от ран.","","Помните о порядке оказания помощи! Находящиеся при смерти солдаты умирают быстрее, чем тяжелораненые. Легкораненые живут дольше всех, потому им надо оказывать помощь ПОСЛЕ того, как перевяжете тех, кто при смерти, и тяжелораненых."}},
[6623] = {"Травматология", {"Пойдите в Павший Молот на нагорье Арати и поговорите с доктором Грегори Виктором о том, чтобы стать травматологом."}},
[6624] = {"Очередность перевязки", {"Окажите помощь пациентам, используя для перевязки их ран очередные перевязочные бинты. Вы должны оказать помощь 15 пациентам прежде, чем 6 из них успеют умереть от ран.","","Помните о порядке оказания помощи! Находящиеся при смерти солдаты умрут быстрее, чем тяжелораненые. Легкораненые могут прожить дольше всех, потому им надо оказывать помощь ПОСЛЕ того, как перевяжете тех, кто при смерти, и тяжелораненых."}},
[6625] = {"Травматологи Альянса", {"Отправляйтесь в Терамор в Пылевых топях и поговорите с доктором Густавом ван Схлиффом насчет зачисления в травматологи Альянса."}},
[6626] = {"Воинство зла", {"Убейте 8 боевых стражей и 8 терноплетов из племени Иглошкурых, а также 8 сектанток из племени Мертвой Головы и возвращайтесь к Мириам Лунной Певице на Курганы Иглошкурых."}},
[6627] = {"Испытание знаний", {"Дайте верный ответ на вопрос Брауга Тусклого Духа и поговорите с ним еще раз. Брауга можно в любое время найти в Когтистых горах."}},
[6628] = {"Испытание знаний", {"Дайте верный ответ на вопрос Парквела Финталласа и поговорите с ним еще раз. Парквелла можно в любое время найти в Подгороде."}},
[6629] = {"Убить Грундига Темное Облако", {"Убейте Грундига Темное Облако и 6 громил из племени Зловещего Тотема и вернитесь к Макабе Плоскому Копыту, который ждет вблизи юго-восточного края Каменного Когтя."}},
[6641] = {"Ворша Хлестунья", {"Охраняйте Муглаша на его пути к жаровне. Помогите ему погасить жаровню, а затем защищайте его, ведя бой с нагами.","","Если вам все удастся, возвращайтесь в форт Зорам'гар и сообщите гонцу клана Песни Войны о смерти Ворши Хлестуньи."}},
[6661] = {"Охота на крыс", {"Поймайте 5 подземных крыс, используя Флейту крысолова, и принесите их Монти. Не забудьте вернуть флейту владельцу."}},
[6662] = {"Братишка Нипси", {"Отвезите Нипси в подземное депо Штормграда коробку таинственного мяса."}},
[6681] = {"Поместье, Черный Ворон", {"Отнесите печать Черного Ворона Фахраду в поместье Черный Ворон, сокрытое среди холмов Хилсбрада.","","Не теряйте бдительности. Поиски поместья – проверка на ловкость."}},
[6701] = {"Эмблемы Синдиката", nil},
[6921] = {"Среди руин", {"Принесите глубинный сердечник Дже'неу Санкри в форт Зорам'гар в Ясеневый лес."}},
[6922] = {"Барон Акванис", {"Принесите странную водяную сферу Дже'неу Санкри в форт Зорам'гар в Ясеневом лесу."}},
[6981] = {"Светящийся осколок", {"Отправляйтесь в Кабестан и найдите там кого-нибудь, кто сможет вам рассказать об этом светящемся осколке.","","Затем отнесите осколок туда, куда вас направят."}},
[7003] = {"Ликвидация великанов", {"Используйте ультрасжиматель Зорбина, чтобы уменьшить великанов любого вида, каких вы найдете в Фераласе. Принесите 15 остатков миниатюризации этих великанов Зорбину Дребезгуну в порт Забытого берега в Фераласе."}},
[7028] = {"Хрустальные орнаменты", {"Соберите 25 терадрических хрустальных орнаментов для Ивы из Пустошей."}},
[7029] = {"Порча Злоязыкого", {"Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона.","","Полейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу.","","Исцелите 8 растений, убивая ядовитые лозы, и вернитесь к Варку Боевому Шраму в Деревню Ночных Охотников."}},
[7041] = {"Порча Злоязыкого", {"Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона.","","Полейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу.","","Исцелите 8 растений, убивая ядовитые лозы, и вернитесь к Талендрии из Высоты Найджела."}},
[7044] = {"Легенды Мародона", {"Добудьте две части скипетра Келебраса – жезл Келебраса и бриллиант Келебраса.","","Найдите способ поговорить с Келебрасом."}},
[7046] = {"Скипетр Келебраса", {"Помогите Селебрасу Искупленному воссоздать скипетр Селебраса.","","По завершении ритуала снова обратитесь к нему."}},
[7064] = {"Яблочко от яблоньки...", {"Убейте принцессу Терадрас и вернитесь к Селендре неподалеку от Деревни Ночных Охотников в Пустошах."}},
[7065] = {"Яблочко от яблоньки...", {"Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши."}},
[7066] = {"Семя Жизни", {"Найдите в Лунной поляне Ремулоса и отдайте ему Семя Жизни."}},
[7067] = {"Инструкции кентавра-парии", {"Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей."}},
[7068] = {"Фрагменты осколка сумрака", {"Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель'наю в Оргриммар."}},
[7070] = {"Фрагменты осколка сумрака", {"Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей."}},
[7321] = {"Нежный черепаховый суп", {"Принесите 10 кусков черепашьего мяса и немного смягчающих пряностей Кристофу Френчу на Мельницу Таррен."}},
[7383] = {"Венец Земли", {"Наполните аметистовый фиал и принесите его Коритрасу Лунному Гневу в Доланаар."}},
[7481] = {"Эльфийские легенды", nil},
[7489] = {"Сеть Лефтендрис", {"Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе."}},
[7492] = {"Лагерь Мохаче", {"Поговорите с Тало Терновым Копытом в Лагере Мохаче в Фераласе."}},
[7541] = {"Служба Орде", nil},
[7701] = {"РАЗЫСКИВАЕТСЯ: надзиратель Мальториус", {"Дворф Черного Железа, вероломный надзиратель Мальториус, скрывается в глубине Шлаковой Ямы в Котле, что в Тлеющем ущелье.","","Убейте надзирателя Мальториуса и принесите его голову дозорному капитану Лоло Долгобою."}},
[7721] = {"Энергия для уменьшения", {"Соберите 10 ядер элементалей воды, убивая морских элементалей и морских валов на Забытом берегу в Фераласе, и принесите их Зорбину Дребезгуну, который находится неподалеку от порта."}},
[7722] = {"Какой еще плавень?", {"Верните секретные документы по изготовлению огненного плавня, украденные надзирателем Мальториусом. Инспектор скорее всего находится в Шлаковой Яме в Котле. Документы верните мастеру-кузнецу Гориврату в Тлеющем ущелье."}},
[7723] = {"Отекшие пальцы", {"По поручению Хансела Большерука убейте 20 тяжелых боевых големов, которых можно найти в землях, окружающих Котел в Тлеющем ущелье. По выполнении задания вернитесь к Ханселу."}},
[7724] = {"Огненная угроза", {"По указанию Хансела Большерука убейте 20 |4опаляющего лавового паука:опаляющих лавовых пауков:опаляющих лавовых пауков; в Тлеющем ущелье. Пауки водятся на вулканических плато и в озерах лавы в Тлеющем ущелье.","","Когда убьете достаточно пауков, вернитесь к Ханселу в Тлеющее ущелье."}},
[7725] = {"Новая ликвидация великанов", {"Используйте ультрасжиматель Зорбина, чтобы уменьшить великанов любого вида, каких вы найдете в Фераласе. Принесите 10 остатков миниатюризации этих великанов Зорбину Дребезгуну в порт Забытого берега в Фераласе."}},
[7726] = {"Новая энергия для уменьшения", {"Соберите 6 ядер элементалей воды, убивая морских элементалей и морских валов на Забытом берегу в Фераласе, и принесите их Зорбину Дребезгуну, который находится неподалеку от порта."}},
[7727] = {"Пламезавры? Ну и название...", {"По поручению Хансела Большерука убейте 20 пламезавров, обитающих в озерах лавы в Шлаковой Яме - это часть Котла в Тлеющем ущелье.","","По выполнении задания вернитесь к Ханселу в Тлеющее ущелье."}},
[7728] = {"УКРАДЕНО: фурма и подзорная труба наблюдателя", {"Найдите и верните фурму и подзорную трубу наблюдателя надсмотрщику Скренджу в Тлеющем ущелье. Единственная известная информация: вещи были украдены дворфами Черного Железа. Подзорная труба является бесценным прибором для наблюдения, а фурма – незаменимым кузнечным инструментом."}},
[7729] = {"ВАКАНСИЯ: устранитель конкурентов", {"Убейте 15 надсмотрщиков и 15 поработителей из клана Черного Железа. По выполнении задания вернитесь к десятнику Скренджу в Тлеющее ущелье."}},
[7730] = {"Вторжение улья Цуккаш", {"Принесите 20 панцирей Цуккаш Хадокену Быстрому Страннику в Лагерь Мохаче в Фераласе."}},
[7731] = {"Жалохвост", {"Убейте жалохвоста в Гудящей Бездне и принести железы ядохлеста Хадокену Быстрому Страннику в Лагерь Мохаче в Фераласе."}},
[7732] = {"Донесение об улье Цуккаш", {"Доставьте отчет о нашествии насекомых-Цуккаш на Лагерь Мохаче Зилзибину Барабанному Бою, который проживает на Волоке в Оргриммаре."}},
[7733] = {"Борьба за качество", {"Принесите 10 шкур йети из пещеры Бешеного оврага Пратту Макгруббену в Крепость Оперенной Луны в Фераласе."}},
[7734] = {"Борьба за качество", {"Принесите 10 шкур йети из пещеры Бешеного оврага Джангору Быстрому Страннику в Лагерь Мохаче в Фераласе."}},
[7735] = {"Безупречная шкура йети", {"Отнесите безупречную шкуру йети Пратту Макгруббену в Крепость Оперенной Луны в Фераласе."}},
[7738] = {"Безупречная шкура йети", {"Отнесите безупречную шкуру йети Джангору Быстрому Страннику в Лагерь Мохаче в Фераласе."}},
