[7828] = {"Охота на бродяг", {"Убейте 15 среброгривых бродяг и 15 среброгривых ревунов по поручению охотника Мархора из деревни Сломанного Клыка во Внутренних землях.","","Мархор сказал, что волки обирают в лесах Внутренних земель."}},
[7829] = {"Охота на дикарей", {"Убейте 20 диких совухов по поручению охотника Мархора из деревни Сломанного Клыка во Внутренних землях.","","Мархор сказал, что совухи обитают в лесах Внутренних земель."}},
[7830] = {"Отмщение за погибших", {"Убейте остроклюва-повелителя небес и принесите его перо охотнику Мархору в деревню Сломанного Клыка.","","Мархор говорил, что остроклюв водятся во Внутренних землях."}},
