[7839] = {"Хулиганы Порочной Ветви", {"Найдите потерянные инструменты кузнеца Углежога из деревни Сломанного Клыка во Внутренних землях.","","Углежог сказал, что инструменты могут быть в одном из храмов троллей Порочной Ветви в северо-восточной части Внутренних земель. Также следует проверить на Осклизлой скале."}},
[7840] = {"Лярд потерял свой обед", {"Найдите обед Лярда из деревни Сломанного Клыка во Внутренних землях.","","Лярд сказал, что потерял свой обед на острове к северу, где могут встретиться тролли из клана Порочной Ветви."}},
[7841] = {"Письмо для Громового Молота", {"Убейте 15 гонцов, 15 разведчиков, 15 стрелков и 15 разведчиков Высокодолья по поручению Отхо Можи'ко из деревни Сломанного Клыка.","","Ночных эльфов из Высокодолья можно найти в Сторожке Кель'Данил в северо-западной части Внутренних земель."}},
[7842] = {"Еще одно письмо для Громового Молота", {"Принесите 10 длинных элегантных перьев Отхо Можи'ко из деревни Сломанного Клыка во Внутренних землях. Перья нужно собрать с местных грифонов, которых можно найти практически в любом месте Внутренних земель."}},
[7843] = {"Последнее письмо для Громового Молота", {"Заберитесь на Заоблачный пик в западной части Внутренних Земель и оставьте возле колодца в центре города последнее предупреждение для Громового Молота. После выполнения задания возвращайтесь к Отхо Можи'ко в деревню Сломанного Клыка.","","Берегитесь дворфов Громового Молота и других сторонников Альянса."}},
[7844] = {"Собратья-каннибалы", {"Убейте 30 охотников за скальпами и 15 ворожеев из племени Порочной Ветви по поручению Яо'джин из деревни Сломанного Клыка.","","Яо'джин сказала, что эти тролли живут близ храмов Шаол-Вата и Агол-Вата в северо-восточной части Внутренних земель."}},
[7845] = {"Похищен старейшина Сломанный Клык!", {"Спасите старейшину Сломанного Клыка из Джинта'Алора по поручению его жены из деревни Сломанного Клыка.","","Старейшину держат в плену на самом верху Джинта'Алор – главного поселения троллей из клана Порочной Ветви, расположенного на юге Внутренних земель."}},
[7846] = {"Отыщите ключ!", {"Убейте хранительницу Хита'йю и заберите у нее ключ от оков, после чего возвращайтесь к старейшине Сломанному Клыку в Джинта'Алор и освободите его."}},
[7847] = {"Возвращение к старейшине племени Сломанного Клыка", {"Возвращайтесь к старейшине Сломанному Клыку и сообщите ей, что ее муж спасен."}},
[7849] = {"Воссоединение останков", {"Принесите охотнику Мархору из деревни Сломанного Клыка во Внутренних землях кости и череп его брата-близнеца.","","Мархор сказал, что останки его брата бросили на съедение слизнюкам и волкам Порочной Ветви – все эти твари водятся неподалеку от вершины Джинта'Алор: слизнюки в компостной яме, а волки – в логове."}},
[7850] = {"Темные сосуды", {"Принесите 10 сосудов с порченой кровью старейшине племени Сломанного Клыка во Внутренние земли. Сосуды с кровью находятся в поселении Джинта'Алор."}},
[7861] = {"РАЗЫСКИВАЕТСЯ: коварная жрица Ведьмиса и ее прислужники", {"Убейте коварную жрицу Ведьмису и 20 стражей Аман'заси из клана Порочной Ветви, после чего доложите старейшине племени Сломанного Клыка в Деревне Сломанного Клыка.","","Коварную жрицу Ведьмису и стражей Аман'заси можно найти в верхней части Джинта'Алора во Внутренних землях."}},
[7862] = {"Требуется: капитан стражи в деревню Сломанного Клыка", {"Убейте 20 берсерков, 20 темных охотников, 20 кровопийц и 20 пожирателей душ из племени Порочной Ветви.","","После выполнения задания вернуться к старейшине Сломанному Клыку во Внутренних землях."}},
