[8356] = {"Поиграй мускулами!", {"Поиграйте мышцами для хозяйки таверны Аллисон и получите от нее за это нугу из Штормграда."}},
[8357] = {"Танец за марципан", {"Потанцуйте для хозяйки таверны Салиенны, и за это вы получите дарнасский марципан!"}},
[8365] = {"Пиратские шляпы", {"Добудьте 20 шляп пиратов Южных Морей и отнесите их Отти Кутюри в Порт Картеля в Танарисе."}},
