[8460] = {"Союзник Древобрюхов", {"Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 6 воинов, 6 землепроходцев и 6 садовников из племени Мертвого Леса. Выполнив поручение, возвращайтесь в южную часть Оскверненного леса к Изумрудному святилищу."}},
[8464] = {"Боевые действия в деревне Зимней Спячки", {"Сальфа хочет, чтобы вы убили 8 |4шамана:шаманов:шаманов; из племени Зимней Спячки, 8 |4дозорного:дозорных:дозорных; из племени Зимней Спячки и 8 |4ведмедя:ведмедей:ведмедей; из племени Зимней Спячки. Сальфа находится у входа в крепость Древобрюхов в Зимних Ключах."}},
[8470] = {"Ритуальный тотем Мертвого Леса", {"Отнесите ритуальный тотем Мертвого Леса в Крепость Древобрюхов и посмотрите, не пригодится ли этот предмет кому из тамошних фурболгов. Фурболги Крепости Древобрюхов не станут говорить с вами – разве что их отношение к вам нейтральное или лучше."}},
[8471] = {"Ритуальный тотем Зимней Спячки", {"Отнесите ритуальный тотем Зимней Спячки в берлогу Древобрюхов и отдайте его фурболгу, который им заинтересуется. Никто из племени Древобрюхов не заговорит с вами, пока вы не завоюете себе среди них достойную репутацию."}},
[8551] = {"Сундук капитана", {"Верните Гекельберри Шмотту из Пиратской бухты его сундук."}},
[8552] = {"Кушак с монограммой", {"Верните кушак с монограммой владельцу."}},
[8553] = {"Капитанская сабля", {"Поговорите с Салагой."}},
[8554] = {"Бой с Неголашем", {"Отнесите 10 жареных крылышек канюка и 5 бутылок экзотического вина в спасательную шлюпку капитана Шмотта.","","Убейте Неголаша и отнесите абордажную саблю Шмотта хозяину в Тернистую долину."}},
