[65597] = {"Связывание", {"С помощью сердец влюбленных призовите и подчините инкуба, затем верните сердца Карендину Халгару в Квартал Магов Подгорода."}},
[65601] = {"Несчастная любовь", {"Поговорите с Магаром в Оргриммаре."}},
[65602] = {"Лучшие друзья", {"Добудьте деревянную статуэтку и принесите ее Гакину Темнопряду в квартал магов Штормграда."}},
[65603] = {"Связывание", {"Воспользуйтесь деревянной статуэткой, чтобы призвать и подчинить инкуба, затем верните статуэтку Гакину Темнопряду. Он будет ждать в \"Забитом ягненке\"."}},
[65604] = {"Связывание", {"С помощью истлевшего платка призовите и подчините своей воле инкуба, затем верните его Ган'рулу Кровавому Глазу в Оргриммаре."}},
[65610] = {"Если бы мы были вместе...", {"Осмотрите озеро Зеркало Небес в Ясеневом лесу и расскажите о находках Ган'рулу Кровавый Глаз в Оргриммаре."}},
[76156] = {"Неслышная поступь Матери-Земли", {"Проберитесь в шахту Торговой Компании к юго-западу от Громового Утеса и соберите 5 шахтерских сефориевых зарядов из тележек со взрывчаткой, а затем вернитесь к Бортону Теневому Тотему в Громовой Утес."}},
[76160] = {"Неслышная поступь Матери-Земли", {"Соберите 8 шишек Неистовства Ветра к северу от Громового Утеса, разотрите их пестиком в ступке и возвращайтесь к Бортону Теневому Тотему в Громовой Утес."}},
[76240] = {"Неслышная поступь Матери-Земли", {"Поймайте или купите сырую блестящую рыбку и покажите Бортону Теневому Тотему из Громового Утеса, как будете ее разделывать набором ножей."}},
[78088] = {"Странный артефакт", {"Принесите сферу Алталакса Делгрену Очистителю на заставу Мейстры в Ясеневом лесу."}},
[78089] = {"В Штормград за советом", {"Принесите сферу Алталакса Катерине Чистой в Штормград."}},
