[91547] = {"Син'дорайский фолиант призыва", {"Отнесите син'дорайский фолиант призыва Зевросту в Оргриммар."}},
[91548] = {"Век'зол", {"С помощью син'дорайского фолианта призыва призовите Век'зола у алтаря Бурь в Выжженных землях. Принесите сердце Век'зола Зевросту в Оргриммар."}},
