[91610] = {"Зимняя рыбалка в пограничье", {"Поймайте 10 зимних кальмаров для Курлла в Храбростане."}},
[91685] = {"Разведка силовой линии", {"Используйте вытягивающий ману жезл на разрыве силовой линии на озере Меннар и принесите Слезы Меннар Изви Златопшик."}},
