[91733] = {"Ниже по течению", {"Найдите отсыревший топор, отсыревшую пилу и отсыревший ящик с инструментами, которые унесло вниз по течению от лесопилки Восточной долины, а затем вернитесь к Ормину Пелфорду."}},
