[93034] = {"Долина Костей", {"Улучшайте отношение к вам племени Гелкис и найдите Нерлока у Долины Костей, далеко на востоке от деревни Гелкис."}},
[93035] = {"Жестокие опустошители", {"Для поддержания отношений с кланом Гелкис убейте 6 |4представителя:представителей:представителей; нежити-опустошителей, а затем встретьтесь с Нерлоком у южного входа в Долину Костей."}},
[93036] = {"Внедрение в секту", {"Поговорите с Санией Серебряный Поток в деревне Шен'дар."}},
[93037] = {"Разоблачение изгоев", {"Для поддержания отношений с кланом Гелкис принесите 1 |4образец:образца:образцов; некромантского одеяния Нерлоку у входа в Долину Костей."}},
[93041] = {"Перед лицом истины", {"Для поддержания отношений с кланом Гелкис принесите проклятый череп и некромантское одеяние Гелкис Уте Мудрой в деревню Гелкис."}},
[93044] = {"Очищающие рыдания", {"Для поддержания отношений с кланом Гелкис принесите Слезы Терадрас Уте Мудрой в деревне Гелкис."}},
[93045] = {"Проверка предположения", {"Для поддержания отношений с кланом Гелкис развейте некромантское проклятие, наложенное на проклятый череп. Добившись успеха, поговорите с Нерлоком близ Долины Костей."}},
[93058] = {"Спасти своих", {"Для поддержания отношений с кланом Гелкис освободите 5 |4пленника:пленников:пленников; из племени Гелкис. Когда закончите, вернитесь к Нерлоку у входа."}},
[93062] = {"Зарывая кости", {"Для поддержания отношений с кланом Гелкис развейте проклятие, наложенное на 8 |4не до конца призванного скелета:не до конца призванных скелетов:не до конца призванных скелетов; в Долине Костей."}},
[93065] = {"Подготовка к битве", {"Поговорите с Валеннией Штормовой Кулак в Ветроягодных низинах."}},
[93089] = {"Что дальше", {"Поговорите с Элаадрином Вечерняя Буря, когда будете готовы покинуть остров Зефрис."}},
[93090] = {"Что дальше", {"Поговорите с Айессой Певицей Рассвета, когда будете готовы покинуть остров Зефрис."}},
[93122] = {"На разведку", {"Для поддержания отношений с кланом Гелкис разведайте места, интересующие кентавров, в Шен'драласе. Затем встретьтесь с Нерлоком у южного входа в Долину Костей и сообщите, что узнали."}},
[93125] = {"Возвращение домой", {"Для поддержания отношений с кланом Гелкис сопроводите Рокрена из убежища изгоев. Затем расскажите о том, что случилось, Нерлоку неподалеку от Долины Костей."}},
[93128] = {"Вождь Джен", {"Для поддержания отношений с кланом Гелкис убейте вождя Джена в деревне Маграм. Добившись успеха, доложите обо всем Уте Мудрой в деревне Гелкис в Пустошах."}},
[93159] = {"Странный отшельник", {"Поговорите со странным отшельником в Теневейном лесу и узнайте о нем больше."}},
[93160] = {"Дары леса", {"Соберите 8 |4теневейный желудь:теневейных желудя:теневейных желудей; в Теневейном лесу."}},
[93162] = {"Голова Уничтожителя", nil},
[93165] = {"Глухое правосудие", {"Добудьте 5 |4ухо:уха:ушей; ал'акетских сектантов в святилище Акира, Теневейном лесу или Ветроягодных низинах."}},
[93172] = {"Освобождение мертвеней", {"Уничтожьте 10 ветряных мертвеней в Теневейном лесу."}},
[93176] = {"Мои маленькие друзья", {"Воспользуйтесь предметами из набора начинающего энтомолога, чтобы найти и поймать древесного тарантула, сенного долгоносика и плотогрыза."}},
[93224] = {"Резные тотемы кентавров", {"Добудьте 5 |4резной тотем:резных тотема:резных тотемов; кентавров, убивая кентавров из любого клана в Пустошах, а затем принесите добычу капитану Пентигасту на Высоту Найджела."}},
[93225] = {"Резные тотемы кентавров", {"Добудьте 5 |4резной тотем:резных тотема:резных тотемов; кентавров, убивая кентавров из любого клана в Пустошах. Принесите добычу Гурде Буйной Гриве на заставе Скитающихся духов."}},
[93226] = {"Как купить дружбу: племя Маграм", nil},
[93227] = {"Как купить дружбу: племя Гелкис", {"Отнесите сумку для тотемов интенданту племени Гелкис в деревню Гелкис в Пустошах, чтобы значительно улучшить отношения с кланом. Отношение кентавров клана Гелкис к вам должно быть как минимум равнодушным."}},
[93317] = {"Сезон ловли крабов", {"Добудьте 6 кусков мяса ветроозерного краба."}},
[93318] = {"РАЗЫСКИВАЕТСЯ: Вулгара Ненасытный", {"Убейте Вулгара Ненасытного на Шен'дарском нагорье и принесите голову Данарию Воющая Вуаль."}},
[93319] = {"Украденные ветрокамни", {"Добудьте 10 украденных ветрокамней у бандитов на Шен'дарском нагорье."}},
[93320] = {"Защита башен", {"Явитесь к Йоране Ветреный Тростник к восточной сторожевой башне в Ветроягодных низинах."}},
[93341] = {"Опустевшие сады", {"Обыщите Опустевшие сады около Шен'драласа и вернитесь к Митере в ближайший храм."}},
[93362] = {"Пропали мои пионы", {"Вырвите растения в Опустевших садах и вернитесь к Митере в Шен'дралас."}},
[93394] = {"Встреча с магистром", {"Найдите магистра Кирандиса в храме Шен'драласа."}},
[93404] = {"Гниение и сожаление", {"Отправляйтесь в Мародон и добудьте флакон с водой Поющих водопадов, а затем принесите его Вещедреву в Опустевшие сады посреди Пустошей."}},
[93429] = {"Братья по крови", {"Убейте 10 Заблудших в Болотном пристанище."}},
[93430] = {"Полцарства за блесну", {"Найдите рыбака из племени Заблудших, укравшего блесну Пеллука, и верните рыболовную снасть хозяину."}},
[93443] = {"Потерянный упаковочный ящик", {"Доставьте потерянный упаковочный ящик Фриз Искродох в Пороховой порт в Лесоречье."}},
[93450] = {"Призрачные неприятности", {"Возьмите недоделанный меч Виндела и придумайте, как переправить его в мир духов. Затем верните ему ирреальный клинок в Шен'дралас."}},
[93459] = {"Больше ал'акетских ушей", nil},
[93461] = {"Добро пожаловать в Шен'дар", {"Поговорите с Ратирилом Солнечное Копье и Кориэллой Спокойный Бриз в деревне Шен'дар."}},
[93464] = {"Заезжий маг", {"Найдите в Пустошах мага, который знает о природе силы дренетиста."}},
[93465] = {"Заметки о дренетисте", {"Принесите заметки Гимаши о дренетисте Азору Альдаморту."}},
[93546] = {"Призрачная железная руда", {"Поищите залежи призрачного железа вокруг Шен'драласа и соберите 10 |4образец:образца:образцов; призрачной железной руды. Вернитесь к Винделу в Шен'дралас, когда закончите."}},
[93552] = {"Сбор ветрокамня", {"Добудьте 15 скоплений ветрокамней из ветрокаменного сырья в Тендалской роще."}},
[93568] = {"Полупереваренный ошейник", {"Верните полупереваренный ошейник тому, кто его узнает. Скорее всего, хозяина надо искать в Шен'драласе в Пустошах или где-то рядом."}},
[93585] = {"Светоч мой", {"Сопроводите отца Таттла в Убежище."}},
[93594] = {"Слово леса", {"Найдите Вещедрева в Опустевших садах около Шен'драласа в Пустошах."}},
[93601] = {"Вали вину на соседа", {"Найдите свинобраза-командира в укрытии Дыбогривов."}},
[93604] = {"Кровь Агамаггана", {"Отправляйтесь в курганы Иглошкурых и достаньте заразную кровь Агамаггана, а затем вернитесь к Ког'тагу Храброму в укрытие Дыбогривов в Пустошах. Ког'таг отдельно напомнил вам, что крови Агамаггана из лабиринтов Иглошкурых будет недостаточно."}},
[93606] = {"Ни хрюка друг другу", {"Разрешите ссору свинобразов, принеся Кволге щедрый букет и заразную кровь Агамаггана. Цветы для букета можно набрать в Опустевших садах около Шен'драласа в Пустошах."}},
[93609] = {"Позабытое ожерелье", {"Принесите позабытое ожерелье Митере в храм Шен'драласа в Пустошах."}},
[93644] = {"Изорванный дневник", {"Согласно тексту, автор дневника может находиться где-то в Шен'драласе."}},
[93663] = {"Пропажа в пути", {"Найдите пропавшего курьера и доставьте отправление Дара в Убежище."}},
[93678] = {"Сокращенные заметки о дренетисте", {"Отнесите переписанные Азором заметки Магтуру в Убежище на болоте Печали."}},
[93679] = {"Видение о сородиче", {"Посмотрите видение Онку вместе с Магтуром."}},
[93680] = {"Ключ от города", {"Добудьте ключ от канализации Даларана по просьбе волхва Вурдена Сиянье Бездны на Мельнице Таррен."}},
[93684] = {"Объект поисков", {"Найдите дренея, занимающегося поисками дренетиста в Выжженных землях."}},
[93685] = {"Служба Кум'ише", {"Добудьте безупречную сферу из дренетиста в Выжженных землях и отнесите ее Кум'ише Коллекционеру.","","Будьте внимательны: этот камень – один из самых редких кристаллов во всем Азероте. Любое существо в этих землях может владеть безупречной сферой из дренетиста."}},
[93735] = {"Сломанный голем", {"Отыщите Риаани Ночной Ветер в западной части Валанаара."}},
[93736] = {"Незваные духи", {"Добудьте 10 сущностей ветряных мертвеней у ветряных мертвеней в Теневейном лесу."}},
[93737] = {"Сломанный голем", {"Поговорите с Лораксом и выслушайте то, что он вам расскажет."}},
[93738] = {"Сломанный голем", {"Отправьтесь с докладом к Айессе Певице Рассвета в Валанаар."}},
[93739] = {"Знакомство с Ордой", {"Получите дальнейшие указания у Назгрела в крепости Громмаш, а затем найдите Вол'джина, Кэрна Кровавое Копыто и леди Сильвану Ветрокрылую и поговорите с ними."}},
[93740] = {"Кровь за кровь", {"Добудьте 10 ал'акетских ветрокаменных талисманов у ал'акетских сектантов в Ветроягодных низинах."}},
