[93786] = {"Послание кровью", {"Убейте 12 |4батрака:батраков:батраков; из Ручьевины и вернитесь к Кром'рошу с победой."}},
[93787] = {"Бесплатная еда", {"Украдите 6 |4сумку с кормом:сумки с кормом:сумок с кормом; с фермы Альянса в Ручьевине и вернитесь к Кром'рошу."}},
