[97243] = {"Зов Огня", {"Принесите факел спящего пламени Олариану Быстрая Вспышка в святилище пламени в Ветроягодных низинах."}},
[97244] = {"Зов Огня", {"Убейте жреца небес Фаладиэля в Ветроягодных низинах и заберите сердце Фаладиэля."}},
