[97246] = {"Обед по расписанию", {"Зайдите в \"Жаровню Борстана\" и скажите, что Татог попросил вас лично отнести Миги его обед."}},
[97249] = {"Любимая еда", {"Отнесите Миги его обед за крепость Громмаш."}},
[97250] = {"Ложное обвинение, очищенное имя", {"Убейте солдат Альянса, хозяйничающих на границе Степей и Пылевых топей, а затем возвращайтесь к рубаке Логмару в Лагерь Таурахо."}},
[97253] = {"Запчасти и детали", {"Соберите 5 |4горсть:горсти:горстей; изощренных деталей в верхнем лагере пиратов к югу от Кабестана, а затем вернитесь к Рениксу Презренному в Кабестан."}},
[97257] = {"Зов Огня", {"Подождите, пока Олариан проводит ритуал у жаровни подношений, и следуйте его указаниям.","","Вам нужно будет доставить Вечное пламя в Валанаар до того, как истечет выделенное время."}},
[97263] = {"Посылка прибыла", {"Доставьте потерянную посылку Элдруну."}},
[97265] = {"Ненависть к Ярой Ненависти", {"Победите разнообразных сатиров из племени Ярой Ненависти в Саргероне в Пустошах, а затем вернитесь к Ака'раю в деревню Ночных Охотников."}},
[97275] = {"Вуут-торопыга", {"Отнесите зелье Йелмака Вууту."}},
[97277] = {"Грунд и Гозвин", {"Найдите лагерь Грунда и Гозвина на северо-западных холмах. Заберите журнал механика Гозвина и убейте снежного леопарда – охотника."}},
[97279] = {"Брошенное оружие", {"Добудьте 6 |4комплект:комплекта:комплектов; брошенного тренировочного оружия и вернитесь к Кзану Шипорубу в Логово."}},
[97281] = {"Назревающая буря", {"Принесите тусклую сферу бури Резлаку, которого можно найти неподалеку от Сухой лощины."}},
[97282] = {"Бурный потенциал", {"Принесите 5 |4заряженный орган:заряженных органа:заряженных органов; рокочущей ящерицы Резлаку, которого можно найти неподалеку от Сухой лощины."}},
[97284] = {"Отмщение Валлариеля", {"Убейте орков из племени Пылающего Клинка в крепости Громового Топора в Пустошах, а затем вернитесь к Валлариелю Истребителю Демонов на Высоту Найджела."}},
[97286] = {"Доступ к исследованиям", nil},
[97287] = {"Хитрые переговоры", {"Поговорите с проекцией верховного мага Модеры рядом с Далараном."}},
[97288] = {"Неизбывные мучения", {"Принесите чудовищную голову мастеру аптекарю Фаранеллу в Подгород."}},
[97289] = {"Неизбывные мучения", {"Принесите голову барона к телу Отмара в Подгород."}},
[97290] = {"Неизбывные мучения", {"Расскажите мастеру аптекарю Фаранеллу в Подгороде о том, что вы узнали."}},
[97291] = {"Неизбывные мучения", {"Добудьте ядовитую черепоганку у Шатенн Гризетт в Торговом квартале, жгуч-траву у наставника травничества и субстанцию агонии у торговца ядами в квартале Разбойников и принесите ингредиенты мастеру аптекарю Фаранеллу в Подгород."}},
[97292] = {"Неизбывные мучения", {"Введите шипящую сыворотку в механизм над туловищем Отмара по просьбе мастера аптекаря Фаранелла."}},
[97326] = {"Камни для отдыха", {"Отнесите 8 |4гладкий валун:гладких валуна:гладких валунов; Тра за крепость Громмаш."}},
[97327] = {"Кошели Черночревов", {"Проникните в логово Черночревов, соберите 5 |4кошель:кошеля:кошелей; Черночревов и принесите Эккалю в руины Эльдарата, что в Азшаре."}},
[97328] = {"Что-нибудь ценное", {"Добудьте 8 |4ящик:ящика:ящиков; украденного груза в руинах Зул'Кунды в Тернистой долине и отнесите кому-нибудь в Пиратскую Бухту."}},
[97329] = {"Где ключ?", {"Добудьте примитивный ключ у троллей в руинах Зул'кунды в Тернистой долине и отнесите его Зиммиксу Искропыху."}},
[97331] = {"Великий побег Зиммикса", {"Проводите Зиммикса Искропыха подальше от руин Зул'Кунды, а затем расскажите о том, что спасли его, управляющему пристанью Подгребаю."}},
[97332] = {"Дважды обманутое ожидание", {"Доставьте дважды перезаказанную посылку управляющему пристанью Просвистуну в Пороховой порт в Лесоречье."}},
[97378] = {"Зеркальная Чешуя", {"Принесите крыло Зеркальной Чешуи Мелору Каменное Копыто в Громовой Утес."}},
[97386] = {"Расплата за Гром'гол", {"Командир Агро'гош из лагеря Гром'гол поручил вам убить огров на холме Мош'Огг."}},
[97405] = {"Жалобы на шум", {"Убейте 3 |4чаротвора:чаротворов:чаротворов;, 3 |4солдата-наемника:солдат-наемников:солдат-наемников;, 3 |4изверга:извергов:извергов; и 3 |4шамана:шаманов:шаманов; из клана Мош'Огг на холме Мош'Огг."}},
[97420] = {"Экономия, переработка и примирение", {"Добудьте 4 |4бочку:бочки:бочек; неочищенной нефти в лагере Торговой Компании на озере Назферити и отнесите Гназу Огнепыху в Тернистую долину."}},
[97453] = {"Борьба с сорняками", {"Уничтожьте 6 |4хищний сорняк:хищных сорняка:хищных сорняков; к югу от Гром'гола, а затем расскажите об этом матери Геммила."}},
[97485] = {"Традиции Утеса", {"Купите связку трав у травницы Ниды, связку сухих кедровых прутьев у торговки товарами для зачаровывателей Наты, жильную нить у продавца товаров для кожевников Маху, а также кремень и трут для церемоний у Наала, торгующего товарами для кулинаров.","","Совместите предметы и развейте получившиеся благовония на Вершине охотников."}},
[97490] = {"Остановить град", {"Найдите великана по имени Злобоград в южных холмах Зимних Ключей и соберите растущий на нем морозный мох."}},
[97530] = {"Пошлина Песчаного Молота", {"Начальник отдела безопасности Чепухастер из порта Картеля в Танарисе просит найти особенно блестящий браслет, потерянный возле поселения Песчаного Молота."}},
[97534] = {"Пыльное дело", {"Принесите 7 |4кусок:куска:кусков; пустынного хлама Квинн в Прибамбасск."}},
[97536] = {"Гномий мусор", {"Джорди Пепелатс хочет, чтобы вы опустошили контейнер радиоактивных отходов в пустыне Танарис на безопасном расстоянии от Прибамбасска и другого мусора, а затем вернулись к нему."}},
[97538] = {"Пигменты для красок", {"Тах Заиндевевшее Копыто в Громовом Утесе просит собрать для него 30 |4стручок:стручка:стручков; лихолиста на Мутном озере."}},
[97539] = {"Шелк для швов", {"Принесите 12 мотков хирургического паучьего шелка доктору Грегори Виктору в Павший Молот на Нагорье Арати."}},
[97540] = {"Оазис", {"Сопроводите утолившего жажду Тоогу к его жене Торте."}},
[97558] = {"Шкуры для Отрекшихся", {"Принесите Шелене Робарт 8 |4мембрану:мембраны:мембран; крыла сумеречницы, 6 |4шкуру:шкуры:шкур; пса тьмы и 3 |4кусок:куска:кусков; кожи мурлока из племени Злобного Плавника."}},
[97583] = {"ВИХЛЯ", {"Купите немного питательной слизи и вернитесь к дружелюбному жизнерадостному слизнюку. Если он выглядит уставшим, попробуйте снова потанцевать с ним, чтобы привлечь его внимание."}},
[97617] = {"Проверка на безопасность", {"Добудьте 8 |4неизученный артефакт:неизученных артефакта:неизученных артефактов;, шахтерскую каску Лиги Исследователей и нетронутую мотыгу, а затем отнесите Горгарону на границу между Лок Моданом и Бесплодными землями."}},
[97663] = {"Припасы и исследования", {"Убейте огров в Знойных Песках, заберите у них украденные припасы и сделайте с их помощью оттиск с камней с письменами, а затем вернитесь к Мус'хале в Каргат."}},
[97884] = {"Арсенал Светоглади", {"Отправьтесь в Светогладь, что в Лесоречье, и добудьте фолиант кузнечных техник рода Тремейн."}},
[97891] = {"Наш пострел доставить зелье успел", {"Доставьте нестабильное зелье доктору Мартину Фелбену в Квартал аптекарей за отведенное время."}},
[97894] = {"Дела в Аубердине", {"Проведайте Горбольда Сталерука в Аубердине на Темных берегах.","","Боргус обмолвился, что туда можно попасть на корабле, отбывающем из порта Штормграда с самого южного причала."}},
