[99204] = {"Скорость ветра", {"Обучитесь навыку верховой езды на уровне подмастерья у Кильдара."}},
[99257] = {"Кристальное сердце", {"Уничтожьте ветхого защитника столпа, добудьте истощенное кристаллическое сердце и принесите его историку Бираксасу в Шен'драласский храм."}},
[99258] = {"Мана-мания", {"Бросьте истощенное кристаллическое сердце в нестабильный разлом маны. Вернитесь к историку Бираксасу в Шен'драласский храм с доказательством успеха или неудачи."}},
